using SalesManagement.Core.Models; using SalesManagement.Core.Quotations; using SalesManagement.Core.Repositories;
namespace SalesManagement.Api.Endpoints;
public static class InquiryEndpoints
{
    public static IEndpointRouteBuilder MapInquiryEndpoints(this IEndpointRouteBuilder endpoints)
    {
        var group = endpoints.MapGroup("/api/inquiries").RequireAuthorization();
        group.MapGet("", async (string? search, Guid? ownerId, Guid? customerId, InquiryStatus? status, bool? overdueOnly, InquiryService service, IUserRepository users, HttpContext c, CancellationToken ct) => Results.Ok((await service.ListAsync(new(search, ownerId, customerId, status, overdueOnly ?? false), await QuotationEndpointSupport.Actor(c, users, ct), ct)).Select(Response)));
        group.MapGet("/{id:guid}", async (Guid id, InquiryService service, IUserRepository users, HttpContext c, CancellationToken ct) => Results.Ok(Response(await service.GetAsync(id, await QuotationEndpointSupport.Actor(c, users, ct), ct))));
        group.MapPost("", async (InquirySaveRequest r, InquiryService service, IUserRepository users, HttpContext c, CancellationToken ct) => Results.Ok(Response(await service.SaveAsync(r.Command(null), await QuotationEndpointSupport.Actor(c, users, ct), ct))));
        group.MapPut("/{id:guid}", async (Guid id, InquirySaveRequest r, InquiryService service, IUserRepository users, HttpContext c, CancellationToken ct) => Results.Ok(Response(await service.SaveAsync(r.Command(id), await QuotationEndpointSupport.Actor(c, users, ct), ct))));
        group.MapPost("/{id:guid}/assign", async (Guid id, AssignRequest r, InquiryService service, IUserRepository users, HttpContext c, CancellationToken ct) => Results.Ok(Response(await service.AssignAsync(id, r.OwnerId, r.ExpectedVersion, await QuotationEndpointSupport.Actor(c, users, ct), ct))));
        group.MapPost("/{id:guid}/status", async (Guid id, StatusRequest r, InquiryService service, IUserRepository users, HttpContext c, CancellationToken ct) => Results.Ok(Response(await service.ChangeStatusAsync(id, r.Status, r.ResultMemo, r.ExpectedVersion, await QuotationEndpointSupport.Actor(c, users, ct), ct))));
        group.MapPost("/{id:guid}/activities", async (Guid id, ActivityRequest r, InquiryService service, IUserRepository users, HttpContext c, CancellationToken ct) => Results.Ok(await service.AddActivityAsync(id, new(r.Kind, r.Body), await QuotationEndpointSupport.Actor(c, users, ct), ct)));
        group.MapPost("/{id:guid}/attachments", async (Guid id, IFormFile file, InquiryService service, IUserRepository users, HttpContext c, CancellationToken ct) => { if (file.Length is 0 or > 10 * 1024 * 1024) return Results.UnprocessableEntity(new { title = "첨부파일은 10MB 이하로 등록해 주세요.", status = 422 }); await using var stream = new MemoryStream(); await file.CopyToAsync(stream, ct); return Results.Ok(AttachmentResponse(await service.AddAttachmentAsync(id, new(file.FileName, file.ContentType, stream.ToArray()), await QuotationEndpointSupport.Actor(c, users, ct), ct))); }).DisableAntiforgery();
        group.MapGet("/{id:guid}/attachments/{attachmentId:guid}", async (Guid id, Guid attachmentId, InquiryService service, IUserRepository users, HttpContext c, CancellationToken ct) => { var row = await service.GetAsync(id, await QuotationEndpointSupport.Actor(c, users, ct), ct); var file = row.Attachments.SingleOrDefault(x => x.Id == attachmentId) ?? throw new KeyNotFoundException(); return Results.File(file.Content, file.ContentType, file.FileName); });
        return endpoints;
    }
    private static object AttachmentResponse(InquiryAttachment a) => new { a.Id, a.InquiryId, a.FileName, a.ContentType, a.Size, a.Sha256, a.UploadedBy, a.UploadedAt };
    private static object Response(CustomerInquiry x) => new { x.Id, x.InquiryNumber, x.Title, x.CustomerId, x.CustomerName, x.ContactName, x.ContactEmail, ownerId = x.OwnerUserId, x.ReceivedAt, x.ResponseDueAt, x.Status, x.Summary, x.ResultMemo, x.Activities, attachments = x.Attachments.Select(AttachmentResponse), linkedQuoteIds = Array.Empty<Guid>(), x.Version };
    public sealed record InquirySaveRequest(string Title, Guid CustomerId, string ContactName, string? ContactEmail, Guid OwnerId, DateOnly ReceivedAt, DateOnly ResponseDueAt, string Summary, long ExpectedVersion = 0) { public SaveInquiryCommand Command(Guid? id) => new(id, Title, CustomerId, ContactName, ContactEmail, OwnerId, ReceivedAt, ResponseDueAt, Summary, ExpectedVersion); }
    public sealed record AssignRequest(Guid OwnerId, long ExpectedVersion); public sealed record StatusRequest(InquiryStatus Status, string? ResultMemo, long ExpectedVersion); public sealed record ActivityRequest(InquiryActivityKind Kind, string Body);
}
